package com.tnr.cityguide.config;
import com.nimbusds.jose.jwk.source.ImmutableSecret;import com.tnr.cityguide.user.UserRepository;import java.nio.charset.StandardCharsets;import java.util.UUID;import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.server.resource.authentication.*;
@Configuration public class SecurityConfig {
 @Bean SecretKey jwtSecretKey(AppProperties p){String s=p.jwt().secret();if(s==null||s.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 bytes");return new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256");}
 @Bean JwtDecoder jwtDecoder(SecretKey key,UserRepository users){NimbusJwtDecoder delegate=NimbusJwtDecoder.withSecretKey(key).macAlgorithm(MacAlgorithm.HS256).build();return token->{Jwt jwt=delegate.decode(token);try{if(!users.existsById(UUID.fromString(jwt.getSubject())))throw new BadJwtException("Token subject no longer exists");}catch(IllegalArgumentException ex){throw new BadJwtException("Invalid token subject",ex);}return jwt;};}
 @Bean JwtEncoder jwtEncoder(SecretKey key){return new NimbusJwtEncoder(new ImmutableSecret<>(key));}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean JwtAuthenticationConverter jwtAuthenticationConverter(){JwtGrantedAuthoritiesConverter a=new JwtGrantedAuthoritiesConverter();a.setAuthoritiesClaimName("role");a.setAuthorityPrefix("ROLE_");JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(a);return c;}
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthenticationConverter converter,ApiAuthenticationEntryPoint entryPoint,ApiAccessDeniedHandler denied)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).formLogin(f->f.disable()).httpBasic(b->b.disable()).exceptionHandling(e->e.authenticationEntryPoint(entryPoint).accessDeniedHandler(denied)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/auth/**","/actuator/health","/uploads/**").permitAll().requestMatchers("/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/**").authenticated().anyRequest().permitAll()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter))).build();}
}
